public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[] visited = new boolean[n];
    boolean[]可达 = new boolean[n];
    for (int[] path : paths) {
        int from = path[0];
        int to = path[1];
       可达[from] = true;
       可达[to] = true;
    }
    if (!可达[start[0]] || !可达[end[0]]) {
        return "cannot be travelled";
    }
    if (start[0] == end[0] && start[1] == end[1]) {
        return "can be travelled";
    }
    Queue<int[]> queue = new LinkedList<>();
    queue.add(start);
    visited[start[0]] = true;
    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        for (int[] path : paths) {
            int from = path[0];
            int to = path[1];
            if (from == current[0] && !visited[to]) {
                visited[to] = true;
                if (to == end[0] && to == end[1]) {
                    return "can be travelled";
                }
                queue.add(new int[]{to, end[1]});
            } else if (to == current[0] && !visited[from]) {
                visited[from] = true;
                if (from == end[0] && from == end[1]) {
                    return "can be travelled";
                }
                queue.add(new int[]{from, end[1]});
            }
        }
    }
    return "cannot be travelled";
}

public static String appx(String word1, String word2) {
    Set<Character> set1 = new HashSet<>();
    for (char c : word1.toCharArray()) {
        set1.add(c);
    }

    Set<Character> set2 = new HashSet<>();
    for (char c : word2.toCharArray()) {
        set2.add(c);
    }

    set1.retainAll(set2);
    int commonLetters = set1.size();

    int lengthSum = word1.length() + word2.length();
    int gcd = gcd(commonLetters, lengthSum);
    commonLetters /= gcd;
    lengthSum /= gcd;

    return "approx(" + word1 + ", " + word2 + ") = " + commonLetters + "/" + lengthSum;
}

