    fibonacci.add(a);
    fibonacci.add(b);
    while (a + b <= k) {
        int next = a + b;
        fibonacci.add(next);
        a = b;
        b = next;
    }
    int count = 0;
    for (int i = fibonacci.size() - 1; i >= 0; i--) {
        if (k >= fibonacci.get(i)) {
            k -= fibonacci.get(i);
            count++;
        }
    }
    return count;
}

