public static int countDigitOne(int n) {
    if (n < 0) return 0;
    int count = 0;
    for (long m = 1; m <= n; m *= 10) {
        long a = n / (m * 10);
        long b = n % m;
        long c = n / m % 10;
        if (c == 0) count += a * m;
        else if (c == 1) count += a * m + b + 1;
        else count += (a + 1) * m;
    }
    return count;
}

