public static int largestRectangleArea(int[] heights) {
    Stack<Integer> stack = new Stack<>();
    int maxArea = 0;
    int i = 0;
    while (i < heights.length) {
        if (stack.isEmpty() || heights[stack.peek()] <= heights[i]) {
            stack.push(i++);
        } else {
            int topOfStack = stack.pop();
            int area = heights[topOfStack] * (stack.isEmpty() ? i : i - stack.peek() - 1);
            maxArea = Math.max(maxArea, area);
        }
    }
    while (!stack.isEmpty()) {
        int topOfStack = stack.pop();
        int area = heights[topOfStack] * (stack.isEmpty() ? i : i - stack.peek() - 1);
        maxArea = Math.max(maxArea, area);
    }
    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }

    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int row = 0, col = 0, d = 0; // d is the direction, 0 for up, 1 for down

    while (row < m && col < n) {
        result[row * n + col] = mat[row][col];

        if (d == 0) {
            if (col == n - 1) {
                row++;
                d = 1;
            } else if (row == 0) {
                col++;
                d = 1;
            } else {
                row--;
                col++;
            }
        } else {
            if (row == m - 1) {
                col++;
                d = 0;
            } else if (col == 0) {
                row++;
                d = 0;
            } else {
                row++;
                col--;
            }
        }
    }

    return result;
}

public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    int len = digits.length;

    // Start from the rightmost digit and move leftwards
    for (int i = len - 2; i >= 0; i--) {
        // If the current digit is greater than the next digit
        if (digits[i] > digits[i + 1]) {
            // Find the smallest digit on the right side of (i-index) but greater than digits[i]
            int smallest = i + 1;
            for (int j = i + 2; j < len; j++) {
                if (digits[j] > digits[i] && digits[j] < digits[smallest]) {
                    smallest = j;
                }
            }

            // Swap the found digit with digits[i]
            char temp = digits[i];
            digits[i] = digits[smallest];
            digits[smallest] = temp;

            // Sort the digits after (i-index) in ascending order
            Arrays.sort(digits, i + 1, len);

            // Convert the digits back to the number
            return Integer.parseInt(new String(digits));
        }
    }

    // If no valid rearrangement is possible
    return -1;
}

